import{_ as o,C as n,c as s,o as c,a3 as e,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Set up accounting","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/accounting-setup.md","filePath":"master/finance/get-started/accounting-setup.md","lastUpdated":1792041590000}'),i={name:"master/finance/get-started/accounting-setup.md"};function u(l,t,h,p,d,g){const a=n("ImagePopup");return c(),s("div",null,[t[0]||(t[0]=e('<h1 id="set-up-accounting" tabindex="-1">Set up accounting <a class="header-anchor" href="#set-up-accounting" aria-label="Permalink to &quot;Set up accounting&quot;">​</a></h1><p>Before a company can book invoices and payments, it needs a chart of accounts, journals, taxes and default settings. The <strong>Set up accounting</strong> step creates all of these for you in one click. You do it once per company.</p><blockquote><p><strong>In simple words:</strong> Click one button, confirm, and your company gets a ready-made set of accounts, journals, taxes and defaults.</p></blockquote><h2 id="when-you-see-this-step" tabindex="-1">When you see this step <a class="header-anchor" href="#when-you-see-this-step" aria-label="Permalink to &quot;When you see this step&quot;">​</a></h2><p>The step shows on the four pages under <code>Accounting → Settings</code>: <strong>Manage Products</strong>, <strong>Manage Taxes</strong>, <strong>Manage Customer Invoice</strong> and <strong>Manage Default Accounts</strong>. Two of them are affected in a clear way. <strong>Manage Taxes</strong> and <strong>Manage Default Accounts</strong> stay empty, with no <strong>Save changes</strong> button, until the company is set up. Instead you see a warning box with the heading <strong>Set up accounting for this company</strong>.</p><p>The box says: &quot;Accounting is not set up for this company yet. Use &#39;Set up accounting&#39; below to create its chart of accounts, journals and default settings.&quot;</p>',6)),r(a,{src:"/images1/finance/accounting_setup_callout.png",alt:"Manage Default Accounts page with the warning box and the Set up accounting for this company link"}),t[1]||(t[1]=e('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Your first company is normally set up already, so you may never see this box. You see it when you add a new company.</p></div><h2 id="how-aureus-decides-a-company-is-set-up" tabindex="-1">How Aureus decides a company is set up <a class="header-anchor" href="#how-aureus-decides-a-company-is-set-up" aria-label="Permalink to &quot;How Aureus decides a company is set up&quot;">​</a></h2><p>A company counts as set up when it has at least one <strong>Sale</strong> journal and one <strong>Purchase</strong> journal. If both exist, the box does not show and the pages work as normal.</p><h2 id="set-up-accounting-1" tabindex="-1">Set up accounting <a class="header-anchor" href="#set-up-accounting-1" aria-label="Permalink to &quot;Set up accounting&quot;">​</a></h2><ol><li>Switch to the company you want to set up, using the company switcher at the top right.</li><li>Go to <code>Accounting → Settings → Manage Default Accounts</code>. The other settings pages work too.</li><li>In the warning box, click <strong>Set up accounting for this company</strong>.</li><li>Aureus asks you to confirm. Click <strong>Confirm</strong>.</li><li>A message <strong>Accounting set up</strong> appears: &quot;Chart of accounts, journals and default settings were created for this company.&quot;</li></ol><p>The page then reloads and shows the normal settings form.</p><h2 id="what-it-creates" tabindex="-1">What it creates <a class="header-anchor" href="#what-it-creates" aria-label="Permalink to &quot;What it creates&quot;">​</a></h2><p>Aureus copies the accounting set-up of a <strong>template company</strong> into your company. A template company is the company that already holds your chart of accounts, journals and taxes. The template is the default company from your general settings (see <a href="./../../general-settings/companies/companies.html">Companies</a>). If none is set, it is the first company created in the system.</p><p>The copy includes:</p><ul><li><strong>Tax groups</strong> and <strong>taxes</strong>.</li><li>The <strong>chart of accounts</strong>, including the parent and sub-account structure.</li><li><strong>Journals</strong>, such as Customer Invoices, Vendor Bills, Bank Transactions, Cash Transactions and Miscellaneous Operations. Journals do not keep the bank account of the template company, so you must link your own.</li><li><strong>Default settings</strong>: the default accounts, the exchange difference journal and the default sales and purchase taxes.</li></ul><p>Amounts in currency fields are set to your company&#39;s own currency.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><ul><li>It does not run if the company is already set up. Nothing is changed or duplicated.</li><li>It does not run for the template company itself. That company needs its own accounting data in place.</li><li>It does not copy invoices, bills, payments or other transactions.</li><li>It does not create bank accounts. Add them under your journals. See <a href="./journals.html">Journals</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Run the step before you create invoices or change settings for the new company. If the template company has no accounting data, there is nothing to copy.</p></div><h2 id="what-to-do-next" tabindex="-1">What to do next <a class="header-anchor" href="#what-to-do-next" aria-label="Permalink to &quot;What to do next&quot;">​</a></h2><ol><li>Open the <a href="./chart-of-accounts.html">Chart of accounts</a> and check the accounts.</li><li>Open <a href="./journals.html">Journals</a> and link the bank account to the Bank journal.</li><li>Review <a href="./default-accounts.html">Default accounts</a> and <a href="./../taxes/tax-settings.html">Tax settings</a>.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Get started with finance</a></li><li><a href="./chart-of-accounts.html">Chart of accounts</a></li><li><a href="./journals.html">Journals</a></li><li><a href="./default-accounts.html">Default accounts</a></li></ul>',18))])}const y=o(i,[["render",u]]);export{f as __pageData,y as default};
